package net.civeira.phylax.feature.identity.user.domain.valueholder;

import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.user.domain.User;
import net.civeira.phylax.feature.identity.user.domain.valueobject.WelcomeAtVO;

class WelcomeAtValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of welcome at of user")
  void test_welcome_at_value_holder_assign_plain_value() {
    Object holder = new Object();
    WelcomeAtValueHolder<Object> value = new WelcomeAtValueHolder<>(holder);
    Assertions.assertSame(
        holder, value.welcomeAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "Setters must return the holder");
    Assertions.assertTrue(value.getWelcomeAtValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        value.getWelcomeAt().orElse(null), "The plain value must be recovered");
    Assertions.assertSame(holder, value.welcomeAtNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getWelcomeAtValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getWelcomeAt().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of welcome at of user")
  void test_welcome_at_value_holder_assign_value_object() {
    Object holder = new Object();
    WelcomeAtValueHolder<Object> value = new WelcomeAtValueHolder<>(holder);
    WelcomeAtVO vo = WelcomeAtVO.from(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertFalse(value.getWelcomeAtValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.welcomeAt(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getWelcomeAtValue().orElseThrow());
    Assertions.assertSame(holder, value.welcomeAt(Optional.empty()));
    Assertions.assertFalse(value.getWelcomeAtValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.welcomeAt(Optional.of(vo)));
    Assertions.assertSame(vo, value.getWelcomeAtValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of welcome at of user against the original")
  void test_welcome_at_value_holder_read() {
    Object holder = new Object();
    WelcomeAtValueHolder<Object> value = new WelcomeAtValueHolder<>(holder);
    WelcomeAtVO vo = WelcomeAtVO.from(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    WelcomeAtVO other = WelcomeAtVO.from(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    User original = Mockito.mock(User.class);
    Mockito.when(original.getWelcomeAtValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readWelcomeAt(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readWelcomeAt(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.welcomeAt(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readWelcomeAt(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readWelcomeAt(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of welcome at of user")
  void test_welcome_at_value_holder_unset() {
    Object holder = new Object();
    WelcomeAtValueHolder<Object> value = new WelcomeAtValueHolder<>(holder);
    WelcomeAtVO vo = WelcomeAtVO.from(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    value.welcomeAt(vo);
    Assertions.assertSame(holder, value.unsetWelcomeAtIfMatches("welcomeAt_other"));
    Assertions.assertTrue(value.getWelcomeAtValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetWelcomeAtIfMatches("welcomeAt"));
    Assertions.assertFalse(value.getWelcomeAtValue().isPresent(),
        "The field name must clear the value");
    value.welcomeAt(vo);
    Assertions.assertSame(holder, value.unsetWelcomeAt());
    Assertions.assertFalse(value.getWelcomeAtValue().isPresent(), "Unset must clear the value");
  }
}
